VIEWS.mkgWa = () => { const st = UI.sub.mkg ||= {}; const W = mkgSt().wa; W.txt ??= "Bonjour {prenom}, " + (S.nom || "") + " vous présente ses nouveautés ! Répondez à ce message pour en savoir plus."; const L = (typeof crmContacts === "function" ? crmContacts() : []).filter(x => mkgTel(x.tel).length >= 8 && (!W.statut || x.statut === W.statut)); const unsub = new Set(((typeof mkSt === "function" && mkSt().unsub) || []).map(x => x.toLowerCase())); const L2 = L.filter(x => !unsub.has((x.email || "").toLowerCase()));
  const i = Math.min(W.i || 0, Math.max(0, L2.length - 1)); const cur = L2[i]; const msg = x => String(W.txt || "").replace(/\{prenom\}/g, ((x && (x.nom || x.societe)) || "").split(/\s+/)[0]).replace(/\{societe\}/g, (x && x.societe) || "").replace(/\{entreprise\}/g, S.nom || "");
  return mkgH("WhatsApp et SMS", "Envoyez un message personnalisé à vos clients et prospects, un par un depuis WhatsApp ou par SMS, ou exportez la liste pour WhatsApp Business.", `<button class="btn" data-act="mkgWaCsv">⇩ Liste (CSV)</button>`) + `<div class="mg-row"><section class="panel"><div class="panel-h"><h2>Message</h2></div><div class="panel-b"><textarea class="in" rows="6" data-ch="mkgWaTxt">${esc(W.txt)}</textarea><p class="small muted">Variables : {prenom} {societe} {entreprise}</p><label class="f">Destinataires<select class="in" data-ch="mkgWaSt"><option value="">Tous (${L.length})</option><option value="client" ${W.statut === "client" ? "selected" : ""}>Clients</option><option value="prospect" ${W.statut === "prospect" ? "selected" : ""}>Prospects</option></select></label></div></section>
  <section class="panel"><div class="panel-h"><h2>Envoi un par un</h2><span class="small muted">${L2.length ? i + 1 + " / " + L2.length : "aucun numéro"}</span></div><div class="panel-b">${cur ? `<div class="mg-wa"><b>${esc(cur.societe || cur.nom)}</b><span class="mono">${esc(cur.tel)}</span><div class="mg-bub">${esc(msg(cur)).replace(/\n/g, "<br>")}</div><div class="row" style="gap:8px;flex-wrap:wrap"><a class="btn pri" href="https://wa.me/${mkgTel(cur.tel)}?text=${encodeURIComponent(msg(cur))}" target="_blank" rel="noopener" data-act="mkgWaSent">💬 WhatsApp</a><a class="btn" href="sms:${esc(cur.tel)}?&body=${encodeURIComponent(msg(cur))}" data-act="mkgWaSent">✉ SMS</a><button class="btn ghost" data-act="mkgWaNext" data-d="-1" ${i ? "" : "disabled"}>‹ Précédent</button><button class="btn ghost" data-act="mkgWaNext" data-d="1" ${i < L2.length - 1 ? "" : "disabled"}>Suivant ›</button></div></div>` : '<p class="empty">Aucun contact avec un numéro de téléphone. Complétez les fiches clients ou les prospects du CRM.</p>'}<p class="small muted">Les contacts désinscrits (E-mail marketing › Audience) sont exclus. WhatsApp impose l'accord du destinataire pour les messages commerciaux.</p></div></section></div>`; };
/* ---------- lien en bio et QR ---------- */
function mkgBioHTML(B) { const c = mkgCfg(); const M = mkgSt(); const lg = typeof fmLogo === "function" && fmLogo(); const links = (B.links && B.links.length ? B.links : mkgBioAuto()).filter(l => l.on !== false && l.u);
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(B.titre || S.nom || "")}</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:${c.font};background:linear-gradient(160deg,${B.c1 || c.c1},${mkgShade(B.c1 || c.c1, -25)});color:#fff;display:flex;justify-content:center;padding:40px 16px}main{width:100%;max-width:480px;text-align:center}.av{width:96px;height:96px;border-radius:50%;background:#fff;margin:0 auto 14px;display:flex;align-items:center;justify-content:center;overflow:hidden;color:${B.c1 || c.c1};font-size:38px;font-weight:800;border:4px solid ${B.c2 || c.c2}}.av img{width:100%;height:100%;object-fit:contain}h1{margin:0 0 6px;font-size:24px}p{opacity:.85;margin:0 0 24px}a{display:block;margin:10px 0;padding:15px 18px;border-radius:14px;background:#fff;color:${B.c1 || c.c1};text-decoration:none;font-weight:700;box-shadow:0 6px 20px rgba(0,0,0,.15);transition:.15s}a:hover{transform:translateY(-2px);background:${B.c2 || c.c2}}footer{margin-top:28px;font-size:12px;opacity:.7}</style></head><body><main><div class="av">${lg && lg.d ? `<img src="${lg.d}" alt="">` : esc((S.nom || "?")[0])}</div><h1>${esc(B.titre || S.nom || "")}</h1><p>${esc(B.bio || "")}</p>${links.map(l => `<a href="${esc(l.u)}" target="_blank" rel="noopener">${esc(l.l)}</a>`).join("")}<footer>© ${new Date().getFullYear()} ${esc(S.nom || "")}</footer></main></body></html>`; }
function mkgBioAuto() { const M = mkgSt(); const c = mkgCfg(); const L = []; if (c.site) L.push({ l: "🌐 Notre site", u: c.site }); mkgOn().forEach(n => { const s = M.nets[n.k] || {}; if (s.h) L.push({ l: (n.k === "wa" ? "💬 Écrivez-nous sur WhatsApp" : "📱 " + n.n), u: n.prof(s.h) }); }); const se = typeof sellerInfo === "function" ? sellerInfo() : {}; if (se.email) L.push({ l: "✉️ Nous écrire", u: "mailto:" + se.email }); if (se.tel) L.push({ l: "📞 Nous appeler", u: "tel:" + se.tel }); return L; }
VIEWS.mkgBio = () => { const B = mkgSt().bio; const c = mkgCfg(); const links = B.links && B.links.length ? B.links : mkgBioAuto(); const wa = (mkgSt().nets.wa || {}).h; const qrT = B.url || (wa ? "https://wa.me/" + mkgTel(wa) : c.site || "");
  return mkgH("Lien en bio et QR codes", "Une page unique avec tous vos liens (réseaux, site, WhatsApp, catalogue) à mettre dans la bio Instagram ou TikTok, et des QR codes pour vos vitrines, cartes et flyers.", `<button class="btn" data-act="mkgBioDl">⇩ Télécharger la page</button>`) + `<div class="mg-row"><section class="panel"><div class="panel-b"><label class="f">Titre<input class="in" value="${esc(B.titre || S.nom || "")}" data-ch="mkgBio" data-f="titre"></label><label class="f">Présentation<input class="in" value="${esc(B.bio || "")}" placeholder="Ex. : Artisan boulanger à Lyon depuis 1998" data-ch="mkgBio" data-f="bio"></label><div class="grid g2"><label class="f">Couleur de fond<input type="color" class="in" value="${esc(B.c1 || c.c1)}" data-ch="mkgBio" data-f="c1"></label><label class="f">Couleur d'accent<input type="color" class="in" value="${esc(B.c2 || c.c2)}" data-ch="mkgBio" data-f="c2"></label></div>
    <h3 class="gdc-h">Boutons</h3>${links.map((l, i) => `<div class="mg-bl"><input type="checkbox" ${l.on !== false ? "checked" : ""} data-ch="mkgBioL" data-i="${i}" data-f="on"><input class="in sm" value="${esc(l.l)}" data-ch="mkgBioL" data-i="${i}" data-f="l"><input class="in sm" value="${esc(l.u)}" data-ch="mkgBioL" data-i="${i}" data-f="u"><button class="btn sm ghost" data-act="mkgBioMv" data-i="${i}" data-d="-1">↑</button><button class="btn sm ghost" data-act="mkgBioDel" data-i="${i}">✕</button></div>`).join("")}<div class="row" style="gap:8px;margin-top:6px"><button class="btn sm" data-act="mkgBioAdd">＋ Bouton</button><button class="btn sm ghost" data-act="mkgBioReset">↺ Recréer depuis mes réseaux</button></div>
    <h3 class="gdc-h">QR code</h3><label class="f">Adresse du QR code (page en ligne, WhatsApp, site…)<input class="in" value="${esc(qrT)}" data-ch="mkgBio" data-f="url"></label><div class="mg-qr">${qrT && window.SCQR ? SCQR(qrT, { size: 180, dark: B.c1 || c.c1 }) : ""}<div><button class="btn sm" data-act="mkgQrDl" data-f="svg">⇩ QR (SVG)</button><button class="btn sm" data-act="mkgQrDl" data-f="png">⇩ QR (PNG)</button><p class="small muted">Mettez la page en ligne (site du client, Netlify, GitHub Pages…) puis collez son adresse ici. Sans hébergement, le QR peut ouvrir directement WhatsApp.</p></div></div></div></section>
  <section class="panel mg-phone"><iframe title="Aperçu" srcdoc="${esc(mkgBioHTML(Object.assign({}, B, { links })))}"></iframe></section></div>`; };
/* ---------- statistiques ---------- */
VIEWS.mkgStat = () => { const M = mkgSt(); const st = UI.sub.mkg ||= {}; const mo = st.smo || new Date().toISOString().slice(0, 7); const S2 = M.stats[mo] || {}; const nets = mkgOn().filter(n => (M.nets[n.k] || {}).h || S2[n.k]); const ks = Object.keys(M.stats).sort().slice(-12);
  const pubs = k => M.posts.filter(p => p.st === "pub" && (p.nets || []).includes(k) && (p.pubAt || p.date || "").startsWith(mo)).length;
  const tot = ks.map(m => Object.values(M.stats[m] || {}).reduce((a, s) => a + (+s.ab || 0), 0)); const mx = Math.max(1, ...tot);
  return mkgH("Statistiques", "Suivez abonnés, portée, interactions et clics par réseau, mois après mois. Les publications sont comptées automatiquement.", `<input type="month" class="in" value="${mo}" data-ch="mkgSMo">`) + `<section class="panel"><div class="tw"><table class="t"><thead><tr><th>Réseau</th><th class="r">Abonnés</th><th class="r">Publications</th><th class="r">Portée</th><th class="r">Interactions</th><th class="r">Clics</th><th class="r">Engagement</th></tr></thead><tbody>${(nets.length ? nets : mkgOn().slice(0, 4)).map(n => { const s = S2[n.k] || {}; const f = k => `<input class="in sm mono r" style="width:100px" value="${s[k] ?? ""}" data-ch="mkgStat" data-k="${n.k}" data-f="${k}">`; return `<tr><td>${mkgLogo(n.k, 20)} ${esc(n.n)}</td><td class="r">${f("ab")}</td><td class="r mono">${pubs(n.k)}</td><td class="r">${f("por")}</td><td class="r">${f("eng")}</td><td class="r">${f("cli")}</td><td class="r mono">${s.por ? (s.eng / s.por * 100).toFixed(1).replace(".", ",") + " %" : "—"}</td></tr>`; }).join("")}</tbody></table></div><div class="panel-b small muted">Relevez ces chiffres dans les statistiques de chaque réseau (Meta Business Suite, TikTok Studio, LinkedIn…) ou laissez votre service relais les compléter.</div></section>
  ${ks.length > 1 ? `<section class="panel" style="margin-top:14px"><div class="panel-h"><h2>Évolution des abonnés</h2></div><div class="panel-b mg-bars">${ks.map((m, i) => `<div><i style="height:${Math.round(tot[i] / mx * 150)}px" title="${tot[i]}"></i><span>${m.slice(5)}/${m.slice(2, 4)}</span><b>${tot[i].toLocaleString("fr-FR")}</b></div>`).join("")}</div></section>` : ""}`; };
